<template><WorkspacePage title="在线用户" subtitle="查看当前登录会话并执行强制退出"><a-form class="query-form" layout="inline"><a-form-item label="登录地址"><a-input v-model:value="queryParams.ipaddr" allow-clear @press-enter="handleQuery" /></a-form-item><a-form-item label="用户名称"><a-input v-model:value="queryParams.userName" allow-clear @press-enter="handleQuery" /></a-form-item><a-form-item><a-button type="primary" @click="handleQuery"><SearchOutlined />搜索</a-button><a-button @click="resetQuery"><ReloadOutlined />重置</a-button></a-form-item></a-form><ResourceTable :columns="columns" :rows="pagedRows" :loading="loading" :pagination="false" row-key="tokenId" :scroll="{x:1000}"><template #bodyCell="{column,record,index}"><template v-if="column.key==='index'">{{(pageNum-1)*pageSize+index+1}}</template><template v-else-if="column.key==='loginTime'">{{parseTime(record.loginTime)}}</template><template v-else-if="column.key==='action'"><a-button type="link" danger @click="handleForceLogout(record)" v-hasPermi="['monitor:online:forceLogout']"><LogoutOutlined />强退</a-button></template></template></ResourceTable><a-pagination v-if="total>0" v-model:current="pageNum" v-model:page-size="pageSize" :total="total" show-size-changer /></WorkspacePage></template>
<script setup name="Online">
import{LogoutOutlined,ReloadOutlined,SearchOutlined}from'@ant-design/icons-vue';import WorkspacePage from '@/components/Antd/WorkspacePage.vue';import ResourceTable from '@/components/Antd/ResourceTable.vue';import feedback from '@/plugins/antdFeedback';import{forceLogout,list as initData}from'@/api/monitor/online'
const onlineList=ref([]),loading=ref(true),total=ref(0),pageNum=ref(1),pageSize=ref(10);const queryParams=reactive({ipaddr:undefined,userName:undefined});const pagedRows=computed(()=>onlineList.value.slice((pageNum.value-1)*pageSize.value,pageNum.value*pageSize.value));const columns=[{title:'序号',key:'index',width:60},{title:'会话编号',dataIndex:'tokenId',key:'tokenId',ellipsis:true},{title:'登录名称',dataIndex:'userName',key:'userName'},{title:'所属部门',dataIndex:'deptName',key:'deptName',mobileHidden:true},{title:'主机',dataIndex:'ipaddr',key:'ipaddr'},{title:'登录地点',dataIndex:'loginLocation',key:'loginLocation',mobileHidden:true},{title:'操作系统',dataIndex:'os',key:'os',mobileHidden:true},{title:'浏览器',dataIndex:'browser',key:'browser',mobileHidden:true},{title:'登录时间',key:'loginTime',width:180},{title:'操作',key:'action',width:90}]
async function getList(){loading.value=true;try{const r=await initData(queryParams);onlineList.value=r.rows;total.value=r.total}finally{loading.value=false}}function handleQuery(){pageNum.value=1;getList()}function resetQuery(){Object.assign(queryParams,{ipaddr:undefined,userName:undefined});handleQuery()}async function handleForceLogout(row){try{await feedback.confirm(`是否确认强退名称为"${row.userName}"的用户?`);await forceLogout(row.tokenId);feedback.msgSuccess('删除成功');getList()}catch{}}getList()
</script><style scoped>.query-form{padding:16px;margin-bottom:12px;border:1px solid var(--workspace-border)}:deep(.ant-pagination){justify-content:flex-end;margin-top:14px}</style>
